const label=x=>{const map={major:['Mayor','Major','Maior'],minor:['Menor natural','Natural minor','Menor natural'],sus4:['Suspendido 4','Suspended 4','Suspenso 4'],dim:['Disminuido','Diminished','Diminuto'],aug:['Aumentado','Augmented','Aumentado'],dom7:['Séptima dominante','Dominant seventh','Sétima dominante'],maj7:['Séptima mayor','Major seventh','Sétima maior'],min7:['Séptima menor','Minor seventh','Sétima menor'],pentMajor:['Pentatónica mayor','Major pentatonic','Pentatônica maior'],pentMinor:['Pentatónica menor','Minor pentatonic','Pentatônica menor'],dorian:['Dórico','Dorian','Dórico'],mixolydian:['Mixolidio','Mixolydian','Mixolídio']};if(x==='minor'&&['chord','chordTheory'].includes(session?.kind))return T('Menor','Minor','Menor');return map[x]?.[['es','en','pt'].indexOf(data.settings.lang)]||window.AcademyDictionary.scales.find(v=>v.id===x)?.names[['es','en','pt'].indexOf(data.settings.lang)]||x;};
const intervalLabel=n=>{const a={1:['2ª menor','Minor 2nd','2ª menor'],2:['2ª mayor','Major 2nd','2ª maior'],3:['3ª menor','Minor 3rd','3ª menor'],4:['3ª mayor','Major 3rd','3ª maior'],5:['4ª justa','Perfect 4th','4ª justa'],6:['Tritono','Tritone','Trítono'],7:['5ª justa','Perfect 5th','5ª justa'],8:['6ª menor','Minor 6th','6ª menor'],9:['6ª mayor','Major 6th','6ª maior'],10:['7ª menor','Minor 7th','7ª menor'],11:['7ª mayor','Major 7th','7ª maior'],12:['Octava','Octave','Oitava']};return a[n][['es','en','pt'].indexOf(data.settings.lang)];};
function say(text){$('globalStatus').textContent=text;}
function save(){if(rejectedData!==null){say(T('El historial anterior no es válido y se ha conservado intacto. Exporta el original desde Ajustes.','Previous history is invalid and was kept untouched. Export the original in Settings.','O histórico anterior é inválido e foi preservado. Exporte o original em Ajustes.'));return false;}try{localStorage.setItem(KEY,JSON.stringify(data));storageOK=true;return true}catch{storageOK=false;say(T('No se pudo guardar. Exporta una copia antes de salir.','Could not save. Export a backup before leaving.','Não foi possível salvar. Exporte uma cópia antes de sair.'));return false;}}
function stop(preserveVoice=false){audioEpoch++;window.AcademyRhythmView?.pause();document.querySelectorAll('.is-playing').forEach(e=>e.classList.remove('is-playing'));if($('demoPosition'))$('demoPosition').textContent='';if(preserveVoice)window.AcademyVoice?.pause();else window.AcademyVoice?.stop();timers.forEach(clearTimeout);timers=[];for(const v of voices){try{v.stop()}catch{}}voices=[];for(const m of masters)m.disconnect();masters=[];rhythm=null;}
async function audio(prepareSamples=true){if(!ctx){ctx=new (window.AudioContext||window.webkitAudioContext)();output=ctx.createDynamicsCompressor();output.threshold.value=-5;output.knee.value=3;output.ratio.value=12;output.attack.value=.003;output.release.value=.12;output.connect(ctx.destination);}await ctx.resume();if(prepareSamples&&!window.AcademySamples.ready(ctx,data.settings.instrument)){const loading=T('Preparando grabaciones del instrumento…','Preparing instrument recordings…','Preparando gravações do instrumento…');say(loading);const loaded=await window.AcademySamples.prepare(ctx,data.settings.instrument);if($('globalStatus').textContent===loading){if(loaded)say('');else say(T('No se pudo cargar el banco. Se usa síntesis; vuelve a intentar con conexión.','The bank could not load. Using synthesis; retry with a connection.','O banco não carregou. Usando síntese; tente novamente com conexão.'));}}return ctx;}
function percussion(when,accent=false,style='click'){if(!ctx||!data.settings.volume)return;const o=ctx.createOscillator(),g=ctx.createGain();o.type=style==='wood'?'triangle':'sine';o.frequency.setValueAtTime(style==='soft'?320:accent?1600:1000,when);o.frequency.exponentialRampToValueAtTime(style==='soft'?130:accent?950:650,when+.055);g.gain.setValueAtTime(Math.max(.0001,data.settings.volume*(style==='soft'?.08:accent?.18:.12)),when);g.gain.exponentialRampToValueAtTime(.0001,when+.065);o.connect(g);g.connect(output);voices.push(o);masters.push(g);o.start(when);o.stop(when+.07);o.onended=()=>{o.disconnect();g.disconnect();voices=voices.filter(v=>v!==o);masters=masters.filter(v=>v!==g);};}
function tone(midi,when,duration=.5,gain=1){if(!ctx||data.settings.volume===0)return;const sampled=window.AcademySamples.play(ctx,output,data.settings,midi,when,duration,gain);if(sampled){const {source,master}=sampled;voices.push(source);masters.push(master);source.onended=()=>{source.disconnect();master.disconnect();voices=voices.filter(v=>v!==source);masters=masters.filter(v=>v!==master);};return;}const preset={piano:{h:[1,.45,.22,.1,.05],a:.008,d:true},guitar:{h:[1,.65,.3,.16,.12,.06],a:.005,d:true},flute:{h:[1,.07,.025],a:.04,d:false},violin:{h:[1,.65,.45,.3,.2,.14,.1],a:.06,d:false}}[data.settings.instrument]||{h:[1,.3,.1],a:.01,d:true};const master=ctx.createGain(),o=ctx.createOscillator(),imag=new Float32Array(preset.h.length+1);masters.push(master);preset.h.forEach((v,i)=>imag[i+1]=v);o.setPeriodicWave(ctx.createPeriodicWave(new Float32Array(imag.length),imag));o.frequency.value=(data.settings.a4||440)*2**((midi-69)/12);const peak=data.settings.volume*.18*gain,attack=Math.min(preset.a,duration/4);master.gain.setValueAtTime(0,when);master.gain.linearRampToValueAtTime(peak,when+attack);if(preset.d)master.gain.exponentialRampToValueAtTime(Math.max(.0001,peak*.25),when+duration*.7);else master.gain.setValueAtTime(peak*.8,when+duration*.7);master.gain.linearRampToValueAtTime(0,when+duration);o.connect(master);master.connect(output);o.start(when);o.stop(when+duration+.02);voices.push(o);o.onended=()=>{o.disconnect();master.disconnect();voices=voices.filter(v=>v!==o);masters=masters.filter(v=>v!==master);};}

async function hear(q){stop();const ticket=audioEpoch;try{await audio();if(ticket!==audioEpoch)return;const start=ctx.currentTime+.08;if(q.kind==='rhythmDictation'){window.AcademyNotation.onsets(q.durations).forEach(p=>tone(84,start+p*60/q.bpm,.1,.7));}else if(q.kind==='rhythmTheory'){tone(72,start,Math.abs(q.figure)*.55,.7);}else if(q.kind==='progression'){q.progression.forEach((chord,i)=>chord.forEach(n=>tone(n,start+i*.85,.75,.55)));}else if(q.kind==='rhythm'){for(const p of q.answer)tone(84,start+p*60/q.bpm,.09,.8);}else if((q.kind==='chord'||q.kind==='chordTheory'||q.kind==='inversion'||q.kind==='chordColor')){q.notes.forEach(n=>tone(n,start,1,.65));}else q.notes.forEach((n,i)=>tone(n,start+i*(q.kind==='scale'?.25:.6),.5));}catch{say(T('No se pudo iniciar el audio. Vuelve a pulsar Escuchar.','Audio could not start. Tap Listen again.','Não foi possível iniciar o áudio. Toque em Ouvir novamente.'));}}
async function demonstrate(steps,seconds=.55,onStep=()=>{},durations=null){stop();const ticket=audioEpoch;try{await audio();if(ticket!==audioEpoch)return;let offset=0;const begin=ctx.currentTime+.06;steps.forEach((step,i)=>{const notes=Array.isArray(step)?step:[step],length=(durations?.[i]||1)*seconds;for(const n of notes)tone(n,begin+offset,Math.max(.06,length*.85),notes.length>1?.55:.8);timers.push(setTimeout(()=>{if(ticket===audioEpoch)onStep(i);},(begin+offset-ctx.currentTime)*1000));offset+=length;});timers.push(setTimeout(()=>{if(ticket===audioEpoch)onStep(-1);},(begin+offset-ctx.currentTime)*1000));}catch{say(T('No se pudo iniciar el sonido. Vuelve a pulsar.','Could not start sound. Tap again.','Não foi possível iniciar o som. Toque novamente.'));}}
